import React from 'react';
import { Link } from 'react-router-dom';
import { useLang } from '../LangContext';

const SOCIALS = [
  {
    href: 'https://web.facebook.com/allthings.ethiopia',
    label: 'Facebook',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
        <path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"/>
      </svg>
    ),
  },
  {
    href: 'https://www.instagram.com/allthings.ethiopia/',
    label: 'Instagram',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <rect x="2" y="2" width="20" height="20" rx="5" ry="5"/>
        <circle cx="12" cy="12" r="4"/>
        <circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/>
      </svg>
    ),
  },
  {
    href: 'https://www.tiktok.com/@allthings.solution',
    label: 'TikTok',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
        <path d="M19.59 6.69a4.83 4.83 0 0 1-3.77-4.25V2h-3.45v13.67a2.89 2.89 0 0 1-2.88 2.5 2.89 2.89 0 0 1-2.89-2.89 2.89 2.89 0 0 1 2.89-2.89c.28 0 .54.04.79.1V9.01a6.33 6.33 0 0 0-.79-.05 6.34 6.34 0 0 0-6.34 6.34 6.34 6.34 0 0 0 6.34 6.34 6.34 6.34 0 0 0 6.33-6.34V8.69a8.18 8.18 0 0 0 4.78 1.52V6.75a4.85 4.85 0 0 1-1.01-.06z"/>
      </svg>
    ),
  },
];

export default function Footer() {
  const { t } = useLang();

  const links = [
    ['/', t.home], ['/clients', t.clients], ['/news', t.news],
    ['/about', t.about], ['/contact', t.contact],
  ];

  return (
    <footer style={{ background: '#111', borderTop: '1px solid #1a1a1a', padding: '40px 24px', marginTop: 80 }}>
      <div style={{ maxWidth: 1200, margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 20 }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
            <img src="/logo.jpg" alt="All Things" style={{ width: 32, height: 32, borderRadius: 6, objectFit: 'cover' }} onError={e => { e.target.style.display = 'none'; }} />
            <span style={{ fontSize: 18, fontWeight: 900 }}>All <span style={{ color: '#f97316' }}>Things</span></span>
          </div>
          <div style={{ color: '#555', fontSize: 13, marginBottom: 14 }}>{t.footerTagline}</div>
          {/* Social icons */}
          <div style={{ display: 'flex', gap: 10 }}>
            {SOCIALS.map(({ href, label, icon }) => (
              <a key={label} href={href} target="_blank" rel="noopener noreferrer" aria-label={label}
                style={{ color: '#555', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  width: 36, height: 36, borderRadius: 8, border: '1px solid #262626',
                  background: '#171717', transition: 'color 0.2s, border-color 0.2s' }}
                onMouseEnter={e => { e.currentTarget.style.color = '#f97316'; e.currentTarget.style.borderColor = '#f97316'; }}
                onMouseLeave={e => { e.currentTarget.style.color = '#555'; e.currentTarget.style.borderColor = '#262626'; }}>
                {icon}
              </a>
            ))}
          </div>
        </div>

        <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
          {links.map(([to, label]) => (
            <Link key={to} to={to} style={{ color: '#555', fontSize: 13 }}
              onMouseEnter={e => e.target.style.color = '#f97316'}
              onMouseLeave={e => e.target.style.color = '#555'}>
              {label}
            </Link>
          ))}
        </div>

        <div style={{ color: '#333', fontSize: 12 }}>{t.copyright}</div>
      </div>
    </footer>
  );
}
